+      title: 'The reveal',
+      narrativeRole: 'setup',
+      message: 'A subject enters a layered world.',
+      blueprint: 'layered-reveal',
+      estimatedDurationSeconds: 6,
+      compositionPlan: {
+        patterns: ['supported-subject'],
+        relationships: [
