+  storyboard.scenes[0].estimatedDurationSeconds = 4;
+  const issues = validateStoryboard(storyboard, {
+    slug: 'rhythm-test',
+    plan: {status: 'resolved', resolved: {sceneCount: 2, durationSeconds: 8}},
+  });
